INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Hallo ihr Lieben die Creme gefällt mir sehr gut ich bin nach wie vor zufrieden, mir ist aufgefallen ,dass die Creme dieses Mal trotz gleicher Inhalte viel flüssiger ist eher die bodylotion!!!  Eine kleine Anmerkung noch die Reinigung lässt sich nicht bis zum Ende aufbrauchen es gibt keine Chance an die letzten ca 2 cm zu kommen! Das sollte man vielleicht noch mal überprüfen!!! Macht weiter so ! Ich bin ein großer Fan von euch !', 'Martina Schlolaut', 'schlolaut@web.de', 'approved', '2024-11-01 23:00:00', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('serum', 5, 'Gute Bewertung', 'Ob Serum, Reinigungsgel oder Creme, ich hab endlich die perfekte Hautpflege für mich gefunden! :) Ich hatte ziemlich Probleme mit Glanz, Großporigkeit und Rötungen. Durch Zufall bin ich auf Norderney am Shop vorbeigelaufen und dachte, dem gebe ich mal eine Chance. Nicht bereut! :) Ich mag das Minimalistische und ebenfalls, dass ich es wirklich auf meine Probleme zuschneiden kann. Meine Haut ist seither viel feinporiger, ebenmäßiger und ruhiger vom Hautbild her geworden, sogar mein Friseur hat mich angesprochen :-D ("Also du brauchst echt kein Makeup, du hast so eine tolle feine Haut!") Dabei hatte ich echt voll Probleme damit. Am Anfang hatte ich etwas mit Purging zu tun (hier und da ein Pickel), aber alles andere war Top. Das hat sich nun auch gelegt. Die Produkte sind sehr ergiebig und halten echt lange. Preis-Leistungs-Verhältnis also wirklich top. Und die Glasbehältnisse sind ein richtiger Hingucker im Bad neben der Umweltfreundlichkeit. Alles in allem bin ich einfach nur super zufrieden und happy und freu mich soooo sehr, endlich die passende Hautpflege gefunden zu haben, mit der meine Haut klarkommt (sie ist seeeehr empfindlich) und alles besser wird, was mir Probleme gemacht hat. Das eigenständige Anrühren war auch easy. Ich bin sehr froh, Herbsom entdeckt zu haben und kann es nur jedem empfehlen!', 'Insa Schmitter', 'insa@wsorg.de', 'approved', '2024-10-29 23:00:00', 0, 0);
